<template><div class="templates"><el-page-header content="话术模板" @back="router.push({name:'SalesAgents'})"/><div class="head"><div><h2>{{ agent?.name || '销售智能体' }}</h2><p>保存可复用的渠道话术提示。</p></div><el-button type="primary" @click="visible=true">新增模板</el-button></div><el-card v-for="item in templates" :key="item.id" class="template-card"><div class="template-title"><strong>{{ item.name }}</strong><el-tag>{{ item.channel }} · {{ item.language }}</el-tag></div><p>{{ item.prompt_text }}</p></el-card><el-empty v-if="!templates.length" description="暂无模板"/><el-dialog v-model="visible" title="新增话术模板" width="620px"><el-form :model="form" label-width="90px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="渠道"><el-select v-model="form.channel"><el-option label="Email" value="email"/><el-option label="WhatsApp" value="whatsapp"/><el-option label="LinkedIn" value="linkedin"/></el-select></el-form-item><el-form-item label="语言"><el-select v-model="form.language"><el-option label="英文" value="en"/><el-option label="中文" value="zh"/></el-select></el-form-item><el-form-item label="提示内容"><el-input v-model="form.prompt_text" type="textarea" :rows="5"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {getSalesAgents,getAgentTemplates,createAgentTemplate,type SalesAgent,type PromptTemplate} from '@/api/salesAgents';const route=useRoute();const router=useRouter();const agent=ref<SalesAgent>();const templates=ref<PromptTemplate[]>([]);const visible=ref(false);const form=reactive({name:'',channel:'email',language:'en',prompt_text:''});async function load(){const id=String(route.query.agent_id);const agents=await getSalesAgents();agent.value=agents.find(item=>item.id===id);templates.value=await getAgentTemplates(id)}async function save(){if(!form.name||!form.prompt_text){ElMessage.warning('请填写模板名称和提示内容');return}await createAgentTemplate(String(route.query.agent_id),form);visible.value=false;Object.assign(form,{name:'',channel:'email',language:'en',prompt_text:''});templates.value=await getAgentTemplates(String(route.query.agent_id));ElMessage.success('模板已保存')}onMounted(load)</script><style scoped>.templates{max-width:1000px;margin:auto}.head{display:flex;justify-content:space-between;align-items:center;margin:26px 0}.head h2{margin:0}.head p{color:#667085}.template-card{margin-bottom:14px}.template-title{display:flex;justify-content:space-between}.template-card p{white-space:pre-wrap;color:#475467;line-height:1.6}</style>
